#include <fstream>
#include <string>
#include <vector>
#include <cmath>
#define main original_multinomial_main
#include "../multinomial-cuda/main.cu"
#undef main
int main(){const int nd=1024,nc=64,r=10;std::vector<float>values(nd*nc),samples(nd);std::vector<int>expected(nd,0),got(nd);for(int d=0;d<nd;d++){samples[d]=float(2*(d%127)+1)/256;float total=0;for(int cat=0;cat<nc;cat++){int k=(cat+d)%4;float x=d%17==0?0:k==2?2:k==0?0:1;values[d*nc+cat]=x;total+=x;}float prev=0;if(total>0)for(int cat=0;cat<nc;cat++){float cur=prev+values[d*nc+cat]/total;if(samples[d]>=prev&&samples[d]<cur){expected[d]=cat;break;}prev=cur;}}
float *ds,*dv;int*out;cudaMalloc(&ds,nd*4);cudaMalloc(&dv,nd*nc*4);cudaMalloc(&out,nd*4);cudaMemcpy(ds,samples.data(),nd*4,cudaMemcpyHostToDevice);cudaMemcpy(dv,values.data(),nd*nc*4,cudaMemcpyHostToDevice);auto launch=[&](){sampleMultinomialOnce<float,float><<<512,256>>>(out,nd,nc,ds,dv,nc,1);};launch();cudaDeviceSynchronize();bool all=true;for(int trial=1;trial<=5;trial++){auto start=std::chrono::steady_clock::now();for(int j=0;j<r;j++)launch();auto error=cudaDeviceSynchronize();double secs=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/r;cudaMemcpy(got.data(),out,nd*4,cudaMemcpyDeviceToHost);bool ok=error==cudaSuccess;int maxabs=0;for(int i=0;i<nd;i++){maxabs=std::max(maxabs,abs(got[i]-expected[i]));ok &=abs(got[i]-expected[i])<=1;}all &=ok;std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/output_trial"+std::to_string(trial)+".bin";std::ofstream(path,std::ios::binary).write((char*)got.data(),nd*4);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":%d,\"max_rel_error\":0,\"timing_region\":\"kernel_launch_loop_per_internal_repeat\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,secs,ok?"true":"false",nd,maxabs,r,path.c_str(),nd);}puts(all?"PASS":"FAIL");return all?0:1;}
